pub fn btn(action:&str,symbol:&str,label:&str,class:&str)->String{format!("<button class=\"btn {class}\" data-action=\"{}\" title=\"{}\" aria-label=\"{}\">{}<span class=\"label\">{}</span></button>",escape(action),escape(label),escape(label),icon(symbol),escape(label))}
fn field(key:&str,label:&str,kind:&str,value:&str)->String{format!("<label class=\"field\"><span>{}</span><input data-field=\"{}\" type=\"{kind}\" value=\"{}\"></label>",escape(label),escape(key),escape(value))}
fn slider(s:&Value,key:&str,label:&str,min:f64,max:f64,step:f64)->String{let val=number(s,key);format!("<div class=\"field\"><label for=\"{key}\">{label}</label><span class=\"value\" id=\"value-{key}\">{val:.1}</span></div><input id=\"{key}\" data-field=\"style-{key}\" data-style=\"{key}\" type=\"range\" min=\"{min}\" max=\"{max}\" step=\"{step}\" value=\"{val}\">")}
fn toggle(s:&Value,key:&str,label:&str)->String{format!("<label class=\"field\"><span>{label}</span><input type=\"checkbox\" data-field=\"style-{key}\" data-style=\"{key}\" {}></label>",if flag(s,key){"checked"}else{""})}
fn colors(s:&Value,key:&str)->String{format!("<div class=\"color-row\"><input type=\"color\" aria-label=\"{key}\" data-field=\"color-{key}\" data-style=\"{key}\" value=\"{}\"><input type=\"text\" aria-label=\"{key} hex\" data-field=\"hex-{key}\" data-style=\"{key}\" value=\"{}\" maxlength=\"7\"></div>",text(s,key),text(s,key))}
fn segments(s:&Value,key:&str,options:&[(&str,&str)])->String{format!("<div class=\"segments\">{}</div>",options.iter().map(|(id,label)|format!("<button class=\"{}\" data-action=\"style:{key}:{id}\">{label}</button>",if text(s,key)==*id{"active"}else{""})).collect::<String>())}
fn palettes(target:&str)->String{format!("<div class=\"palette-title\">PALETTES</div><div class=\"palette\">{}</div>",PALETTES.iter().enumerate().map(|(i,(name,a,b))|format!("<button class=\"swatch\" title=\"{name}\" aria-label=\"{name}\" data-action=\"palette:{target}:{i}\" style=\"background:linear-gradient(145deg,{a},{b})\"></button>")).collect::<String>())}
