fn settings(a:&App,out:&mut String){
 if flag(&a.settings,"appHost"){*out+=&format!("<h3>Desktop app</h3><div class=\"muted\">Version {} · Editor {}</div><div class=\"modal-actions\">{}{} </div><div class=\"progress\">{}</div>",escape(text(&a.settings,"appVersion")),escape(text(&a.settings,"editorVersion")),btn("check-updates","download","Check for updates","outlined"),btn("connect-resolve","pool",if flag(&a.settings,"resolveConnected"){"Resolve connected"}else{"Connect Resolve"},"outlined"),escape(text(&a.settings,"updateStatus")));}

 *out+=&format!("<h3>Appearance</h3><div class=\"segments\"><button data-action=\"theme-light\" class=\"{}\">Light</button><button data-action=\"theme-dark\" class=\"{}\">Dark</button></div><h3>Quick search</h3><select data-field=\"shortcut-preset\">",if a.theme=="light"{"active"}else{""},if a.theme=="dark"{"active"}else{""});for i in 0..5{let s=Shortcut::preset(i);*out+=&format!("<option value=\"{i}\" {}>{}{}</option>",if a.shortcut==s{"selected"}else{""},s.label(),if i==0{" (default)"}else{""});}*out+=&format!("<option value=\"custom\" {}>Custom</option></select><div class=\"folder-row\"><span>{}</span>{}</div>",if (0..5).all(|i|a.shortcut!=Shortcut::preset(i)){"selected"}else{""},if a.recording{"Press a key combination…".into()}else{escape(&a.shortcut.label())},btn("record","rename",if a.recording{"Cancel"}else{"Record shortcut"},"outlined"));
 if a.native{*out+="<h3>Folders</h3>";for(k,label)in [("rawFolder","Raw icon library"),("outputFolder","Generated icons")]{*out+=&format!("<div class=\"muted\">{label}</div><div class=\"folder-row\"><span title=\"{}\">{}</span>{}</div>",escape(text(&a.settings,k)),escape(if text(&a.settings,k).is_empty(){"Choose a folder"}else{text(&a.settings,k)}),btn(&format!("folder:{k}"),"folder","Choose","outlined"));}*out+="<h3>Timeline</h3><select data-field=\"setting-trackMode\">";for(id,label)in [("auto","Automatic · above overlapping clips"),("manual","Manual track")]{*out+=&format!("<option value=\"{id}\" {}>{label}</option>",if text(&a.settings,"trackMode")==id{"selected"}else{""});}*out+="</select>";if text(&a.settings,"trackMode")=="manual"{*out+=&field("setting-track","Video track","number",&a.settings["track"].to_string());*out+="<select data-field=\"setting-position\">";for(id,label)in [("playhead","At playhead"),("end","At end")]{*out+=&format!("<option value=\"{id}\" {}>{label}</option>",if text(&a.settings,"position")==id{"selected"}else{""});}*out+="</select>";}*out+="<span class=\"muted\">PNG duration follows Resolve’s Standard Still Duration.</span>";}
 *out+=&format!("<h3>Icon library</h3><div class=\"muted\">{} icons · {} collections · {:.1} MB compressed</div><input data-field=\"pack-search\" placeholder=\"Find a collection…\" value=\"{}\"><div class=\"pack-list\">",a.catalog["count"].as_u64().unwrap_or(0),a.catalog["collections"].as_array().map_or(0,|v|v.len()),number(&a.catalog,"compressedBytes")/1e6,escape(&a.pack_query));if let Some(packs)=a.catalog["collections"].as_array(){for p in packs{if !format!("{} {}",text(p,"name"),text(p,"prefix")).to_lowercase().contains(&a.pack_query.to_lowercase()){continue}let id=text(p,"prefix");*out+=&format!("<div class=\"pack-row\"><label><input type=\"checkbox\" data-field=\"pack-{id}\" {}><span>{}</span></label><small>{} · {:.1} MB</small><a href=\"{}\" target=\"_blank\" rel=\"noopener\" title=\"License\">↗</a></div>",if a.pack_selection.contains(id){"checked"}else{""},escape(text(p,"name")),p["count"],number(p,"bytes")/1e6,escape(text(&p["license"],"url")));}}*out+="</div><div class=\"modal-actions\">";*out+=&btn("pack-color","sparkle","Select colorful","outlined");*out+=&btn("pack-all","check","Select all","outlined");if a.native{*out+=&btn("download-packs","download","Download selected","primary");}else{*out+="<a class=\"btn primary\" href=\"https://github.com/toolatebysakib/icon-studio/releases/download/v4.0.0/icon-library-rust.zip\">Download full library</a>";}*out+=&format!("</div><div class=\"progress\">{}</div><a class=\"btn outlined\" href=\"https://github.com/toolatebysakib/icon-studio/releases/latest/download/IconStudio-Setup.exe\">{} Download Windows app</a><a class=\"btn outlined\" href=\"https://github.com/toolatebysakib/icon-studio/releases/latest/download/icon-studio-resolve.zip\">Classic Resolve script</a><a class=\"license-info\" href=\"library/LICENSES.txt\" target=\"_blank\">Collection licenses and credits</a>",escape(&a.library_progress),icon("download"));
}
